        index += 1
        start_index = index
        while index < len(s):
            char = s[index]
            if char == '"':
                return s[start_index:index], index + 1
            elif char == '\\':
                index += 2  # skip escape character and next char
            else:
                index += 1
        raise ValueError("Unterminated string")

    def parse_number(index):
        start_index = index
        if s[index] == '-':
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
