    """
    Parse a JSON string into Python objects using a state machine approach. The parser handles 
    strings, numbers, booleans, null, arrays, and objects by traversing the input string character by 
    character and accumulating values based on the context.
    """
    class Parser:
        def __init__(self, s):
            self.s = s
            self.pos = 0
            self.length = len(s)

        def parse(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Unexpected end of input")
            char = self.s[self.pos]
            if char == '{':
                return self.parse_object()
            elif char == '[':
                return self.parse_array()
            elif char == '"':
                return self.parse_string()
            elif char in '-0123456789':
                return self.parse_number()
            elif self.s.startswith('true', self.pos):
                self.pos += 4
                return True
            elif self.s.startswith('false', self.pos):
                self.pos += 5
                return False
            elif self.s.startswith('null', self.pos):
                self.pos += 4
                return None
            else:
                raise ValueError(f"Unexpected character: {char}")

        def parse_object(self):
            obj = {}
            self.pos += 1  # Skip '{'
            self.skip_whitespace()
            if self.s[self.pos] == '}':
                self.pos += 1
                return obj
            while True:
                key = self.parse_string()
                self.skip_whitespace()
                if self.s[self.pos] != ':':
                    raise ValueError("Expected ':'")
                self.pos += 1  # Skip ':'
                self.skip_whitespace()
                value = self.parse()
                obj[key] = value
                self.skip_whitespace()
                if self.s[self.pos] == '}':
                    self.pos += 1
                    return obj
                elif self.s[self.pos] != ',':
                    raise ValueError("Expected ',' or '}'")
                self.pos += 1  # Skip ','

        def parse_array(self):
            arr = []
            self.pos += 1  # Skip '['
            self.skip_whitespace()
            if self.s[self.pos] == ']':
                self.pos += 1
                return arr
            while True:
                value = self.parse()
                arr.append(value)
                self.skip_whitespace()
                if self.s[self.pos] == ']':
                    self.pos += 1
                    return arr
                elif self.s[self.pos] != ',':
                    raise ValueError("Expected ',' or ']'")
                self.pos += 1  # Skip ','

        def parse_string(self):
            self.pos += 1  # Skip initial '"'
            start = self.pos
            result = []
            while self.pos < self.length:
