                            self.pos += 1
                        else:
                            raise ValueError(f"Invalid escape character: {escape_char}")
                    start = self.pos
                else:
                    self.pos += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.s[self.pos] == '-':
                self.pos += 1
            if self.s[self.pos] == '0':
                self.pos += 1
            else:
                if not ('1' <= self.s[self.pos] <= '9'):
