            return float(self.s[start:self.pos]) if '.' in self.s[start:self.pos] or 'e' in self.s[start:self.pos] or 'E' in self.s[start:self.pos] else int(self.s[start:self.pos])

        def skip_whitespace(self):
            while self.pos < self.length and self.s[self.pos] in ' \t\n\r':
                self.pos += 1

    parser = Parser(s)
